const input = $json.body ?? $json;
const deal = input.deal ?? input;
const outcome = String(deal.negotiation_outcome ?? deal.outcome ?? '').toLowerCase();
const leadId = deal.lead_id ?? null;
const dealId = deal.deal_id ?? null;
const propertyId = deal.property_id ?? null;
const contractPrice = Number(deal.contract_price ?? deal.accepted_price ?? deal.counteroffer_amount ?? NaN);
const adjustedMao = Number(deal.adjusted_mao ?? deal.dynamic_mao ?? NaN);
const sellerResponse = String(deal.seller_response ?? deal.response_text ?? '').trim();
const blockers = Array.isArray(deal.blockers) ? deal.blockers : [];
const base = { workflow:"WF-220", lead_id:leadId, deal_id:dealId, property_id:propertyId, outcome, seller_response:sellerResponse, blockers };
let state="needs_review", route="WF-126", reason="Outcome requires human review.";
if (["accepted","accept","accepted_counteroffer","contract_ready","contract_trigger"].includes(outcome)) {
  if (!leadId || !dealId || !propertyId || !Number.isFinite(contractPrice)) { state="blocked"; reason="Missing contract identity or accepted price."; }
  else if (Number.isFinite(adjustedMao) && contractPrice > adjustedMao) { state="blocked"; reason="Accepted price exceeds dynamic MAO protection."; }
  else if (blockers.length) { state="blocked"; reason="Deal has unresolved blockers."; }
  else { state="contract_trigger"; route="WF-201"; reason="Negotiation produced a contract-ready outcome within MAO."; }
} else if (["rejected","declined","seller_rejected"].includes(outcome)) {
  state="rejection_reengagement"; route="WF-202"; reason="Seller rejected the current offer; re-engagement or alternative disposition is required.";
} else if (["walk_away","walk-away","passed"].includes(outcome)) {
  state="walk_away_reengagement"; route="WF-202"; reason="Acquisition was walked away from; preserve re-engagement path where appropriate.";
} else if (["counteroffer","counter","revised_offer"].includes(outcome)) {
  state="revised_offer_follow_up"; route="WF-215"; reason="Negotiation produced a counter/revised offer requiring another controlled offer cycle.";
} else if (["timeout","no_response","seller_silent"].includes(outcome)) {
  state="reengagement_required"; route="WF-202"; reason="Seller did not respond within the expected negotiation window.";
}
const result = {...base,state,route,reason,requires_human_review:["blocked","needs_review","rejection_reengagement","walk_away_reengagement"].includes(state),contract_price:Number.isFinite(contractPrice)?contractPrice:null,adjusted_mao:Number.isFinite(adjustedMao)?adjustedMao:null};
return [{json:result}];
